window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8942ecef9d44efd6"]={"versions": [{"id": "FIG-8942ecef9d44efd6", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Blockdiagramm zur schematischen Datenfeldaufteilung (Frame Format / PDU-Layout) eines FlexRay-Transport-Layer-Frames (FrTp N-PDU) innerhalb des AUTOSAR-FlexRay-Transport-Protocol-Moduls (FrTp). Das Diagramm veranschaulicht die logische Schachtelung und Segmentierung von Nutzdaten und Steuerfeldern bei der Übertragung über den FlexRay-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Der Frame gliedert sich linear in drei aufeinanderfolgende funktionale Segmente:</p>\n<ul class=\"fig-list\"><li>Address Information (grünes Blockelement): Enthält Quell- und Zieladressierungsinformationen bzw. Adressierungsflags für das FrTp-Routing.\n</li><li>Protocol Control Information (PCI, orangefarbenes Blockelement): Beinhaltet TP-spezifische Kontrollinformationen wie Frame-Typ (z. B. StartFrame, ConsecutiveFrame, SingleFrame, FlowControl) sowie Längenangaben oder Sequenznummern.\n</li><li>Data (Payload) (gelbes Blockelement mit Farbverlauf): Repräsentiert das eigentliche Datennutzlastfeld zur Aufnahme der segmentierten oder unsegmentierten oberen PDU-Daten (z. B. PduR / Dcm).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die lineare Anordnung definiert die Serialisierungsreihenfolge im PDU-Bytestrom von links nach rechts: Bei der Kapselung stellt FrTp den Nutzdaten (Data / Payload) die Protocol Control Information und optional die Address Information voran, bevor die resultierende N-PDU an die darunterliegende Kommunikationsschicht (FlexRay Interface, FrIf) übergeben wird. Auf Empfängerseite erfolgt das Parsen und Extrahieren in derselben Reihenfolge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung fixiert den normativen Aufbau der Protokollrahmen für das FlexRay Transport Protocol. Entwickler müssen bei der PDU-Konfiguration und Frame-Assemblierung beachten, dass die PCI und etwaige Adressierungs-Header Bytekontingente der verfügbaren FlexRay-PDU-Payload belegen, wodurch sich die maximal nutzbare Nutzdatenlänge (Netto-Payload) je Frame entsprechend reduziert.</p>"}, {"id": "FIG-f472a16399b3f2cf", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Blockdiagramm zur schematischen Datenfeldaufteilung (Frame Format / PDU-Layout) eines FlexRay-Transport-Layer-Frames (FrTp N-PDU) innerhalb des AUTOSAR-FlexRay-Transport-Protocol-Moduls (FrTp). Das Diagramm veranschaulicht die logische Schachtelung und Segmentierung von Nutzdaten und Steuerfeldern bei der Übertragung über den FlexRay-Bus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Der Frame gliedert sich linear in drei aufeinanderfolgende funktionale Segmente:</p>\n<ul class=\"fig-list\"><li>Address Information (grünes Blockelement): Enthält Quell- und Zieladressierungsinformationen bzw. Adressierungsflags für das FrTp-Routing.\n</li><li>Protocol Control Information (PCI, orangefarbenes Blockelement): Beinhaltet TP-spezifische Kontrollinformationen wie Frame-Typ (z. B. StartFrame, ConsecutiveFrame, SingleFrame, FlowControl) sowie Längenangaben oder Sequenznummern.\n</li><li>Data (Payload) (gelbes Blockelement mit Farbverlauf): Repräsentiert das eigentliche Datennutzlastfeld zur Aufnahme der segmentierten oder unsegmentierten oberen PDU-Daten (z. B. PduR / Dcm).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die lineare Anordnung definiert die Serialisierungsreihenfolge im PDU-Bytestrom von links nach rechts: Bei der Kapselung stellt FrTp den Nutzdaten (Data / Payload) die Protocol Control Information und optional die Address Information voran, bevor die resultierende N-PDU an die darunterliegende Kommunikationsschicht (FlexRay Interface, FrIf) übergeben wird. Auf Empfängerseite erfolgt das Parsen und Extrahieren in derselben Reihenfolge.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung fixiert den normativen Aufbau der Protokollrahmen für das FlexRay Transport Protocol. Entwickler müssen bei der PDU-Konfiguration und Frame-Assemblierung beachten, dass die PCI und etwaige Adressierungs-Header Bytekontingente der verfügbaren FlexRay-PDU-Payload belegen, wodurch sich die maximal nutzbare Nutzdatenlänge (Netto-Payload) je Frame entsprechend reduziert.</p>"}], "trans": [{"from": "FIG-8942ecef9d44efd6", "to": "FIG-f472a16399b3f2cf", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
